// Package structure
// domain/
//   - entities/
//   - usecases/
// data/
//   - repositories/
//   - datasources/
// presentation/
//   - viewmodel/
//   - view/

// 1. Entity Task
data class Task(
    val id: Long,
    val title: String,
    val description: String = "",
    val isCompleted: Boolean = false
)

// 2. Use Cases
typealias TaskResult = Result<List<Task>>

class GetTasks(
    private val repository: TaskRepository
) {
    suspend operator fun invoke(): TaskResult {
        return try {
            Result.success(repository.getTasks())
        } catch (e: Exception) {
            Result.failure(e)
        }
    }
}

class AddTask(
    private val repository: TaskRepository
) {
    suspend operator fun invoke(task: Task): TaskResult {
        return try {
            repository.addTask(task)
            Result.success(emptyList())
        } catch (e: Exception) {
            Result.failure(e)
        }
    }
}

// 3. Repository interface
interface TaskRepository {
    suspend fun getTasks(): List<Task>
    suspend fun addTask(task: Task)
    suspend fun deleteTask(id: Long)
}

// 3.1. Repository Implementation
class TaskRepositoryImpl(
    private val remoteDataSource: TaskDataSource,
    private val localDataSource: TaskDataSource
) : TaskRepository {
    override suspend fun getTasks(): List<Task> {
        // Logique de récupération (ex: local d'abord, sinon remote)
        return localDataSource.getTasks()
    }

    override suspend fun addTask(task: Task) {
        localDataSource.addTask(task)
        remoteDataSource.addTask(task)
    }

    override suspend fun deleteTask(id: Long) {
        localDataSource.deleteTask(id)
        remoteDataSource.deleteTask(id)
    }
}

// 4. DataSource interface
interface TaskDataSource {
    suspend fun getTasks(): List<Task>
    suspend fun addTask(task: Task)
    suspend fun deleteTask(id: Long)
}

// 4.1. Local DataSource (Room)
class LocalTaskDataSource(
    private val taskDao: TaskDao
) : TaskDataSource {
    override suspend fun getTasks(): List<Task> {
        return taskDao.getAll().first()
    }

    override suspend fun addTask(task: Task) {
        taskDao.insert(task)
    }

    override suspend fun deleteTask(id: Long) {
        taskDao.deleteById(id)
    }
}

// 4.2. Remote DataSource (Network)
class RemoteTaskDataSource(
    private val api: TaskApi
) : TaskDataSource {
    override suspend fun getTasks(): List<Task> {
        return api.getTasks()
    }

    override suspend fun addTask(task: Task) {
        api.addTask(task)
    }

    override suspend fun deleteTask(id: Long) {
        api.deleteTask(id)
    }
}

// 5. ViewModel
class TodoViewModel(
    private val getTasks: GetTasks,
    private val addTask: AddTask
) : ViewModel() {
    private val _tasks = MutableStateFlow<Result<List<Task>>>(Result.success(emptyList()))
    val tasks: StateFlow<Result<List<Task>>> = _tasks.asStateFlow()

    fun loadTasks() {
        viewModelScope.launch {
            _tasks.value = getTasks()
        }
    }

    fun addTask(title: String) {
        val task = Task(
            id = System.currentTimeMillis(),
            title = title
        )
        viewModelScope.launch {
            _tasks.value = addTask(task)
        }
    }
}

